PRAGMA foreign_keys = ON;

CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'America/Chicago', default_minimum_call_minutes INTEGER NOT NULL DEFAULT 240, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE people (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, person_type TEXT NOT NULL DEFAULT 'other', default_rate_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE roles (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, description TEXT, default_rate_cents INTEGER NOT NULL DEFAULT 0, minimum_call_minutes INTEGER, active INTEGER NOT NULL DEFAULT 1, UNIQUE (organization_id, name));
CREATE TABLE person_roles (person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, rate_override_cents INTEGER, PRIMARY KEY (person_id, role_id));
CREATE TABLE events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, job_number TEXT, date TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, location_name TEXT, street_address TEXT, map_link TEXT, description TEXT, instructions TEXT, status TEXT NOT NULL DEFAULT 'draft', minimum_call_minutes INTEGER, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE event_role_requirements (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, role_id TEXT NOT NULL REFERENCES roles(id), positions_required INTEGER NOT NULL DEFAULT 1, positions_filled INTEGER NOT NULL DEFAULT 0, rate_cents INTEGER NOT NULL DEFAULT 0, minimum_call_minutes INTEGER);
CREATE TABLE assignments (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, person_id TEXT NOT NULL REFERENCES people(id), role_id TEXT NOT NULL REFERENCES roles(id), status TEXT NOT NULL DEFAULT 'assigned', hourly_rate_cents INTEGER NOT NULL DEFAULT 0, minimum_call_minutes INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(event_id, person_id, role_id));
CREATE TABLE opportunities (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, role_id TEXT NOT NULL REFERENCES roles(id), positions_required INTEGER NOT NULL, positions_filled INTEGER NOT NULL DEFAULT 0, estimated_hours REAL NOT NULL DEFAULT 0, rate_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'open', updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE opportunity_responses (id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id) ON DELETE CASCADE, person_id TEXT NOT NULL REFERENCES people(id), response TEXT NOT NULL, responded_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(opportunity_id, person_id));
CREATE TABLE availability_blocks (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, start_date TEXT NOT NULL, end_date TEXT NOT NULL, start_time TEXT, end_time TEXT, status TEXT NOT NULL, note TEXT);
CREATE TABLE timesheets (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), person_id TEXT NOT NULL REFERENCES people(id), role_id TEXT NOT NULL REFERENCES roles(id), event_date TEXT NOT NULL, scheduled_start TEXT NOT NULL, scheduled_end TEXT NOT NULL, actual_start TEXT, actual_end TEXT, break_minutes INTEGER NOT NULL DEFAULT 0, actual_hours REAL, approved_hours REAL, hourly_rate_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft', audit_note TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX idx_events_date ON events(organization_id, date);
CREATE INDEX idx_people_org ON people(organization_id, status);
CREATE INDEX idx_availability_person_date ON availability_blocks(person_id, start_date, end_date);
